    <script>document.addEventListener('DOMContentLoaded', () => { const labels = @json($dates->map(fn ($date) => \Carbon\Carbon::parse($date)->format('d M'))); const income = labels.map((_, i) => Number(@json($dates->map(fn ($date) => (float) ($chart->get($date.'|income') ?? 0)))[i])); const expense = labels.map((_, i) => Number(@json($dates->map(fn ($date) => (float) ($chart->get($date.'|expense') ?? 0)))[i])); new Chart(document.getElementById('summaryChart'), { type: 'line', data: { labels, datasets: [{ label: 'Income', data: income, borderColor: '#28A096', backgroundColor: 'rgba(40,160,150,.12)', fill: true }, { label: 'Expense', data: expense, borderColor: '#EB5724', backgroundColor: 'rgba(235,87,36,.12)', fill: true }, { label: 'Profit', data: income.map((value, i) => value - expense[i]), borderColor: '#F2A24B', borderDash: [5, 5] }] }, options: { responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false } } }); });</script>
